package main
import ("context"; "database/sql"; "fmt")
// The transaction value is a *sql.Tx and is rolled back on every early return.
func transfer(ctx context.Context,db *sql.DB,fromID,toID string,amount int64)error{tx,err:=db.BeginTx(ctx,nil);if err!=nil{return err};defer tx.Rollback();if _,err:=tx.ExecContext(ctx,"UPDATE accounts SET balance=balance-? WHERE id=? AND balance>=?",amount,fromID,amount);err!=nil{return err};if _,err:=tx.ExecContext(ctx,"UPDATE accounts SET balance=balance+? WHERE id=?",amount,toID);err!=nil{return err};return tx.Commit()}
func main(){fmt.Println("Configure a local database/sql driver before invoking transfer.")}
